import json
import math

# Charpit system for F = p*q - u = 0:
#   dx/dt = q, dy/dt = p, du/dt = 2u, dp/dt = p, dq/dt = q
# Initial strip: x(0)=0, y(0)=tau, u(0)=tau^2, with compatibility q0 = 2*tau, p0 = tau/2.
# Candidate curves are tested against these conditions using exact-form values
# and central finite differences (h = 1e-6), tolerance 1e-6.

H = 1e-6
TOL = 1e-6
TAUS = [0.7, -1.3, 2.1]
SS = [0.0, 0.4, -0.8]

def d_ds(f, t, s):
    return (f(t, s + H) - f(t, s - H)) / (2 * H)

def d_dtau(f, t, s):
    return (f(t + H, s) - f(t - H, s)) / (2 * H)

options = {
    "1": lambda t, s: (3 * t * (math.exp(s) - 1), t / 2 * (math.exp(-s) + 1), t * t * math.exp(-2 * s)),
    "2": lambda t, s: (2 * t * (math.exp(s) - 1), t * (2 * math.exp(2 * s) - 1), t * t / 2 * (1 + math.exp(-2 * s))),
    "3": lambda t, s: (2 * t * (math.exp(s) - 1), t / 2 * (math.exp(s) + 1), t * t * math.exp(2 * s)),
    "4": lambda t, s: (t * (math.exp(-s) - 1), -2 * t * (math.exp(-s) - 1.5), t * t * (2 * math.exp(-2 * s) - 1)),
}

def component(f, idx):
    return lambda t, s: f(t, s)[idx]

def check_option(f):
    X = component(f, 0)
    Y = component(f, 1)
    U = component(f, 2)
    evidence = {"ode_ok": True, "initial_ok": True, "compat_ok": True}
    for t in TAUS:
        # Initial curve x(0)=0, y(0)=tau, u(0)=tau^2
        if abs(X(t, 0.0)) > TOL or abs(Y(t, 0.0) - t) > TOL or abs(U(t, 0.0) - t * t) > TOL:
            evidence["initial_ok"] = False
        # Strip compatibility: q0 = x_s(0) must equal 2*tau (from u_tau = q*y_tau with y_tau = 1)
        if abs(d_ds(X, t, 0.0) - 2 * t) > TOL:
            evidence["compat_ok"] = False
        for s in SS:
            p = d_ds(Y, t, s)   # p = dy/ds
            q = d_ds(X, t, s)   # q = dx/ds
            u = U(t, s)
            if abs(p * q - u) > TOL:
                evidence["ode_ok"] = False
            if abs(d_ds(U, t, s) - 2 * u) > TOL:
                evidence["ode_ok"] = False
            if abs(d_ds(lambda tt, ss: d_ds(Y, tt, ss), t, s) - p) > 1e-4:
                evidence["ode_ok"] = False
            if abs(d_ds(lambda tt, ss: d_ds(X, tt, ss), t, s) - q) > 1e-4:
                evidence["ode_ok"] = False
    evidence["valid"] = evidence["ode_ok"] and evidence["initial_ok"] and evidence["compat_ok"]
    return evidence

results = {k: check_option(v) for k, v in options.items()}
valid = [k for k, r in results.items() if r["valid"]]

if len(valid) == 1:
    final = valid[0]
else:
    final = "UNSUPPORTED"

output = {
    "final_answer": final,
    "evidence": {
        "charpit_system": "dx/ds=q, dy/ds=p, du/ds=2u, dp/ds=p, dq/ds=q",
        "initial_p0_q0": "p0=tau/2, q0=2*tau",
        "valid_options": valid,
        "per_option": results,
    },
}
print(json.dumps(output))
